/**
 * Chess piece SVG styles. Each style has 12 templates (6 pieces x 2 colors)
 * with __FILL__ and __STROKE__ placeholders for theme colors.
 *
 * Styles:
 * - Staunton: Cburnett set (public domain, Wikipedia)
 * - Alpha, Pirouetti, Chessnut: lichess.org piece sets (public domain)
 */
import type { PieceSymbol, Color } from 'chess.js';

export type PieceStyleId = 'staunton' | 'alpha' | 'pirouetti' | 'chessnut';

export interface PieceStyleInfo {
  id: PieceStyleId;
  name: string;
  description: string;
}

export const PIECE_STYLES: PieceStyleInfo[] = [
  { id: 'staunton', name: 'Staunton', description: 'Classic tournament' },
  { id: 'alpha', name: 'Alpha', description: 'Modern bold' },
  { id: 'pirouetti', name: 'Pirouetti', description: 'Clean minimalist' },
  { id: 'chessnut', name: 'Chessnut', description: 'Rounded friendly' },
];

export interface PieceThemeColors {
  whiteFill: string;
  whiteStroke: string;
  blackFill: string;
  blackStroke: string;
  /**
   * Optional SVG <defs> (e.g. gradients) injected into every rendered piece.
   * Fills may reference them via url(#id).
   */
  defs?: string;
  /**
   * Optional SVG filters applied to the whole piece, per side
   * (e.g. metallic emboss, engraved inner line). Values like 'url(#id)'.
   */
  whiteFilter?: string;
  blackFilter?: string;
}

